rollback.sql:
DO $$
DECLARE fn record;
BEGIN
    FOR fn IN
        SELECT p.oid::regprocedure AS signature
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public'
          AND p.proname LIKE 'logos\_%'
    LOOP
        EXECUTE format('ALTER FUNCTION %s RESET search_path', fn.signature);
    END LOOP;
END $$;

changeSet.sql:
ALTER TABLE log_entry ADD COLUMN updated_at timestamptz;

CREATE OR REPLACE FUNCTION logos_log_entry_stamp_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_catalog
AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_log_entry_updated_at
    BEFORE INSERT OR UPDATE ON log_entry
    FOR EACH ROW
    EXECUTE FUNCTION logos_log_entry_stamp_updated_at();

CREATE TABLE log_entry_hourly_stats ( bucket_hour timestamptz NOT NULL, model_id integer, provider_id integer, team_id integer, user_id integer, result_status result_status_enum, was_cold_start boolean NOT NULL, requests bigint NOT NULL, queue_seconds_sum double precision, queue_seconds_count bigint NOT NULL, run_seconds_sum double precision, run_seconds_count bigint NOT NULL, error_count bigint NOT NULL, total_tokens bigint NOT NULL, cost_micro_cents bigint NOT NULL );
-- NULLS NOT DISTINCT because most of the grain is nullable: without -- it two rows for the same (hour, no model, no team) would both be -- allowed and the hour would silently double. CREATE UNIQUE INDEX ux_log_entry_hourly_stats_grain ON log_entry_hourly_stats (bucket_hour, model_id, provider_id, team_id, user_id, result_status, was_cold_start) NULLS NOT DISTINCT;
CREATE INDEX idx_log_entry_hourly_stats_bucket ON log_entry_hourly_stats (bucket_hour);
-- One row. processed_through is the instant the last completed pass -- read up to: everything changed at or before it is reflected in the -- table above, and it is what the reader's freshness guard measures. CREATE TABLE log_entry_rollup_state ( only_row boolean PRIMARY KEY DEFAULT TRUE, processed_through timestamptz NOT NULL, CONSTRAINT log_entry_rollup_state_single CHECK (only_row) );

CREATE OR REPLACE FUNCTION logos_stats_rollup_apply(p_hours timestamptz[]) RETURNS bigint LANGUAGE plpgsql SET search_path = public, pg_catalog AS $$ DECLARE affected bigint; BEGIN IF p_hours IS NULL OR array_length(p_hours, 1) IS NULL THEN RETURN 0; END IF;
DELETE FROM log_entry_hourly_stats s WHERE s.bucket_hour = ANY (p_hours);
INSERT INTO log_entry_hourly_stats ( bucket_hour, model_id, provider_id, team_id, user_id, result_status, was_cold_start, requests, queue_seconds_sum, queue_seconds_count, run_seconds_sum, run_seconds_count, error_count, total_tokens, cost_micro_cents) SELECT date_trunc('hour', COALESCE(le.timestamp_forwarding, le.timestamp_request, le.timestamp_response)), le.model_id, le.provider_id, le.team_id, le.user_id, le.result_status, COALESCE(le.was_cold_start, FALSE), COUNT(*), SUM(CASE WHEN le.timestamp_request IS NOT NULL AND le.timestamp_forwarding IS NOT NULL THEN EXTRACT(EPOCH FROM (le.timestamp_forwarding - le.timestamp_request)) END), COUNT(*) FILTER (WHERE le.timestamp_request IS NOT NULL AND le.timestamp_forwarding IS NOT NULL), SUM(CASE WHEN le.timestamp_forwarding IS NOT NULL AND le.timestamp_response IS NOT NULL THEN EXTRACT(EPOCH FROM (le.timestamp_response - le.timestamp_forwarding)) END), COUNT(*) FILTER (WHERE le.timestamp_forwarding IS NOT NULL AND le.timestamp_response IS NOT NULL), COUNT(*) FILTER (WHERE le.result_status IS DISTINCT FROM 'success' OR (le.error_message IS NOT NULL AND le.error_message <> '')), COALESCE(SUM(tok.total_tokens), 0)::bigint, COALESCE(SUM(lec.cost_micro_cents), 0)::bigint FROM log_entry le LEFT JOIN LATERAL ( SELECT SUM(ut.token_count) AS total_tokens FROM usage_tokens ut JOIN token_types tt ON tt.id = ut.type_id WHERE ut.log_entry_id = le.id AND tt.name = 'total_tokens' ) tok ON TRUE LEFT JOIN log_entry_cost lec ON lec.log_entry_id = le.id WHERE date_trunc('hour', COALESCE(le.timestamp_forwarding, le.timestamp_request, le.timestamp_response)) = ANY (p_hours) GROUP BY 1, 2, 3, 4, 5, 6, 7;
GET DIAGNOSTICS affected = ROW_COUNT; RETURN affected; END; $$;

CREATE OR REPLACE FUNCTION logos_stats_rollup_pass(p_write_lag interval)
RETURNS TABLE (hours_rebuilt bigint, rows_written bigint)
LANGUAGE plpgsql
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_last    timestamptz;
    v_cutoff  timestamptz := now() - p_write_lag;
    v_open    timestamptz := date_trunc('hour', now());
    v_hours   timestamptz[];
    v_written bigint;
BEGIN
    SELECT processed_through INTO v_last FROM log_entry_rollup_state;
    IF v_last IS NULL THEN
        RAISE EXCEPTION 'log_entry_rollup_state is empty; the rollup was never initialised';
    END IF;

    SELECT COALESCE(array_agg(DISTINCT h), '{}')
      INTO v_hours
      FROM (
            SELECT generate_series(
                       LEAST(date_trunc('hour', le.timestamp_request),
                             date_trunc('hour', COALESCE(le.timestamp_forwarding,
                                                         le.timestamp_request,
                                                         le.timestamp_response))),
                       GREATEST(date_trunc('hour', le.timestamp_request),
                                date_trunc('hour', COALESCE(le.timestamp_forwarding,
                                                            le.timestamp_request,
                                                            le.timestamp_response))),
                       interval '1 hour') AS h
              FROM log_entry le
             WHERE le.updated_at > v_last
               AND le.updated_at <= v_cutoff
            UNION
            SELECT generate_series(date_trunc('hour', v_last), v_open - interval '1 hour',
                                   interval '1 hour')
           ) dirty
     WHERE h IS NOT NULL
       AND h < v_open;

    v_written := logos_stats_rollup_apply(v_hours);

    UPDATE log_entry_rollup_state SET processed_through = v_cutoff;

    hours_rebuilt := COALESCE(array_length(v_hours, 1), 0);
    rows_written  := v_written;
    RETURN NEXT;
END;
$$;

INSERT INTO log_entry_rollup_state (only_row, processed_through)
VALUES (TRUE, now());

SELECT logos_stats_rollup_apply(ARRAY(
    SELECT DISTINCT date_trunc('hour', COALESCE(le.timestamp_forwarding,
                                                le.timestamp_request,
                                                le.timestamp_response))
    FROM log_entry le
    WHERE COALESCE(le.timestamp_forwarding, le.timestamp_request, le.timestamp_response)
          < date_trunc('hour', now())
));

ANALYZE log_entry_hourly_stats;
